package org.brightstats.data;
import com.google.gson.*;
import java.util.*;

/** Data-only subgraph interchange with column-name rebinding and unique pasted names. */
public final class DiagramClipboard {
    private DiagramClipboard(){}
    public record Pasted(JsonObject diagram,int[] added){public Pasted{diagram=diagram.deepCopy();added=added.clone();}@Override public JsonObject diagram(){return diagram.deepCopy();}@Override public int[] added(){return added.clone();}}
    public static void validate(JsonObject graph,int columns){JsonArray blocks=graph.getAsJsonArray("blocks"),edges=graph.getAsJsonArray("edges");if(blocks==null||edges==null||blocks.size()>500||edges.size()>10000)throw new IllegalArgumentException("Invalid bounded diagram.");Set<String> names=new HashSet<>();for(var element:blocks){var block=element.getAsJsonObject();String name=block.get("name").getAsString().trim();if(name.isEmpty()||name.length()>256||!names.add(name))throw new IllegalArgumentException("Construct names must be nonempty and unique.");org.brightstats.stats.PlsSem.Mode.valueOf(block.get("mode").getAsString());var indicators=block.getAsJsonArray("columns");if(indicators==null||indicators.isEmpty())throw new IllegalArgumentException("A construct needs at least one indicator.");Set<Integer> used=new HashSet<>();for(var value:indicators){int column=value.getAsBigDecimal().intValueExact();if(column<0||column>=columns||!used.add(column))throw new IllegalArgumentException("Invalid or duplicate construct indicator.");}for(String position:List.of("x","y"))if(block.has(position)&&!Double.isFinite(block.get(position).getAsDouble()))throw new IllegalArgumentException("Construct position must be finite.");if(block.has("initialWeights")){var weights=block.getAsJsonArray("initialWeights");if(weights.size()!=indicators.size())throw new IllegalArgumentException("Initial weight count differs.");for(var value:weights)if(!Double.isFinite(value.getAsDouble()))throw new IllegalArgumentException("Initial weights must be finite.");}}List<List<Integer>> children=new ArrayList<>();int[] incoming=new int[blocks.size()];for(int i=0;i<incoming.length;i++)children.add(new ArrayList<>());Set<String> pairs=new HashSet<>();for(var element:edges){var edge=element.getAsJsonObject();int source=edge.get("source").getAsBigDecimal().intValueExact(),target=edge.get("target").getAsBigDecimal().intValueExact();if(source<0||target<0||source>=blocks.size()||target>=blocks.size()||source==target||!pairs.add(source+":"+target))throw new IllegalArgumentException("Invalid or duplicate connection.");children.get(source).add(target);incoming[target]++;}ArrayDeque<Integer> ready=new ArrayDeque<>();for(int i=0;i<incoming.length;i++)if(incoming[i]==0)ready.add(i);int visited=0;while(!ready.isEmpty()){int source=ready.removeFirst();visited++;for(int target:children.get(source))if(--incoming[target]==0)ready.add(target);}if(visited!=blocks.size())throw new IllegalArgumentException("PLS path diagrams cannot contain directed cycles.");}
    public static String copy(JsonObject graph,int[] selected,List<String> columnNames){validate(graph,columnNames.size());if(selected.length==0)throw new IllegalArgumentException("Select constructs before copying.");JsonArray source=graph.getAsJsonArray("blocks"),blocks=new JsonArray(),edges=new JsonArray();Map<Integer,Integer> mapping=new LinkedHashMap<>();for(int index:selected){if(index<0||index>=source.size()||mapping.putIfAbsent(index,mapping.size())!=null)throw new IllegalArgumentException("Invalid diagram selection.");blocks.add(source.get(index).deepCopy());}for(var element:graph.getAsJsonArray("edges")){var edge=element.getAsJsonObject();int from=edge.get("source").getAsInt(),to=edge.get("target").getAsInt();if(mapping.containsKey(from)&&mapping.containsKey(to)){JsonObject copied=edge.deepCopy();copied.addProperty("source",mapping.get(from));copied.addProperty("target",mapping.get(to));edges.add(copied);}}JsonObject payload=new JsonObject();payload.addProperty("format","bright-stats-diagram");payload.addProperty("formatVersion",1);payload.add("columnNames",new Gson().toJsonTree(columnNames));payload.add("blocks",blocks);payload.add("edges",edges);return payload.toString();}
    public static Pasted paste(JsonObject existing,String text,List<String> columnNames,double offsetX,double offsetY){if(text==null||text.length()>2000000||!Double.isFinite(offsetX)||!Double.isFinite(offsetY))throw new IllegalArgumentException("Invalid or oversized diagram clipboard.");validate(existing,columnNames.size());JsonObject payload=JsonParser.parseString(text).getAsJsonObject();if(!payload.has("format")||!payload.get("format").getAsString().equals("bright-stats-diagram")||payload.get("formatVersion").getAsBigDecimal().intValueExact()!=1)throw new IllegalArgumentException("Clipboard does not contain a supported Bright-Stats diagram.");List<String> original=new ArrayList<>();for(var value:payload.getAsJsonArray("columnNames"))original.add(value.getAsString());if(new HashSet<>(columnNames).size()!=columnNames.size()||new HashSet<>(original).size()!=original.size())throw new IllegalArgumentException("Column names must be unique for clipboard rebinding.");validate(payload,original.size());JsonObject result=existing.deepCopy();JsonArray blocks=result.getAsJsonArray("blocks"),edges=result.getAsJsonArray("edges");int base=blocks.size();if(base+payload.getAsJsonArray("blocks").size()>500)throw new IllegalArgumentException("Pasted diagram exceeds the construct limit.");Set<String> names=new HashSet<>();for(var block:blocks)names.add(block.getAsJsonObject().get("name").getAsString());int[] added=new int[payload.getAsJsonArray("blocks").size()];for(int index=0;index<added.length;index++){var block=payload.getAsJsonArray("blocks").get(index).getAsJsonObject().deepCopy();String originalName=block.get("name").getAsString(),name=originalName;int suffix=1;while(names.contains(name))name=originalName+" (copy "+suffix+++")";if(name.length()>256)throw new IllegalArgumentException("Pasted construct name exceeds its limit.");names.add(name);block.addProperty("name",name);JsonArray columns=new JsonArray();for(var value:block.getAsJsonArray("columns")){String nameOfColumn=original.get(value.getAsBigDecimal().intValueExact());int mapped=columnNames.indexOf(nameOfColumn);if(mapped<0)throw new IllegalArgumentException("Current data has no indicator named "+nameOfColumn);columns.add(mapped);}block.add("columns",columns);block.addProperty("x",(block.has("x")?block.get("x").getAsDouble():140)+offsetX);block.addProperty("y",(block.has("y")?block.get("y").getAsDouble():130)+offsetY);blocks.add(block);added[index]=base+index;}for(var element:payload.getAsJsonArray("edges")){var edge=element.getAsJsonObject().deepCopy();edge.addProperty("source",base+edge.get("source").getAsBigDecimal().intValueExact());edge.addProperty("target",base+edge.get("target").getAsBigDecimal().intValueExact());edges.add(edge);}validate(result,columnNames.size());return new Pasted(result,added);}
}
